FUNCTION_BLOCK FB
VAR_INPUT
    openBtn    : BOOL;
    closeBtn   : BOOL;
    openLimit  : BOOL;
    closeLimit : BOOL;
    obstacle   : BOOL;
END_VAR
VAR_OUTPUT
    motorUp    : BOOL := FALSE;
    motorDown  : BOOL := FALSE;
    errorFlag  : BOOL := FALSE;
END_VAR
VAR
    currentState : INT := 0; (* 0=IDLE, 1=OPENING, 2=CLOSING, 3=FAULT *)
    prevOpenBtn  : BOOL := FALSE;
    prevCloseBtn : BOOL := FALSE;
END_VAR

    // Edge detection
    IF openBtn AND NOT prevOpenBtn THEN
        prevOpenBtn := openBtn;
        IF currentState = 0 AND NOT openLimit THEN
            currentState := 1;
        END_IF
    ELSIF NOT openBtn THEN
        prevOpenBtn := FALSE;
    END_IF

    IF closeBtn AND NOT prevCloseBtn THEN
        prevCloseBtn := closeBtn;
        IF currentState = 0 AND NOT closeLimit THEN
            currentState := 2;
        END_IF
    ELSIF NOT closeBtn THEN
        prevCloseBtn := FALSE;
    END_IF

    // State machine
    CASE currentState OF
        3: // FAULT
            motorUp   := FALSE;
            motorDown := FALSE;
            IF openBtn AND closeBtn THEN
                errorFlag  := FALSE;
                currentState := 0;
            END_IF

        0: // IDLE
            motorUp   := FALSE;
            motorDown := FALSE;

        1: // OPENING
            motorUp   := TRUE;
            motorDown := FALSE;
            IF openLimit THEN
                motorUp   := FALSE;
                currentState := 0;
            ELSIF obstacle THEN
                motorUp   := FALSE;
                errorFlag  := TRUE;
                currentState := 3;
            END_IF

        2: // CLOSING
            motorUp   := FALSE;
            motorDown := TRUE;
            IF obstacle THEN
                motorDown  := FALSE;
                currentState := 1;
            ELSIF closeLimit THEN
                motorDown  := FALSE;
                currentState := 0;
            END_IF
    END_CASE
END_FUNCTION_BLOCK
